package br.com.admeclesial.application.financeiro; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class ContaAPagarApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final ContaAPagarRepository repo; final OrganizacaoEclesialRepository org; final FornecedorRepository fornecedores; final ObrigacaoRepasseRepository obrigacoes; final ParcelaAPagarRepository parcelas; public ContaAPagarApplicationService(ContaAPagarRepository r,OrganizacaoEclesialRepository o,FornecedorRepository f,ObrigacaoRepasseRepository ob,ParcelaAPagarRepository p){repo=r;org=o;fornecedores=f;obrigacoes=ob;parcelas=p;} @Transactional public ContaAPagar criar(ContaAPagarRequest r){if(seguranca!=null)seguranca.validarAcesso(r.organizacaoEclesialUuid());var o=org.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new IllegalArgumentException("Organização não encontrada."));if(!o.isAtivo())throw new IllegalArgumentException("Organização inativa.");if(r.dataVencimento().isBefore(r.dataEmissao()))throw new IllegalArgumentException("Vencimento inválido.");if((r.fornecedorUuid()==null)==(r.obrigacaoRepasseUuid()==null))throw new IllegalArgumentException("Informe fornecedor ou obrigação de repasse.");var e=new ContaAPagar();e.setOrganizacaoEclesialId(o.getId());e.setFornecedorId(r.fornecedorUuid()==null?null:fornecedores.findByUuid(r.fornecedorUuid()).orElseThrow(()->new IllegalArgumentException("Fornecedor não encontrado.")).getId());e.setObrigacaoRepasseId(r.obrigacaoRepasseUuid()==null?null:obrigacoes.findByUuid(r.obrigacaoRepasseUuid()).orElseThrow(()->new IllegalArgumentException("Obrigação de repasse não encontrada.")).getId());e.setDescricao(r.descricao().trim());e.setDataEmissao(r.dataEmissao());e.setDataVencimento(r.dataVencimento());e.setValorTotal(r.valorTotal());e.setStatus(StatusContaAPagar.ABERTA);e=repo.save(e);var p=new ParcelaAPagar();p.setContaAPagarId(e.getId());p.setNumero(1);p.setVencimento(e.getDataVencimento());p.setValor(e.getValorTotal());p.setStatus(StatusParcelaAPagar.ABERTA);parcelas.save(p);return e;} @Transactional(readOnly=true) public List<ContaAPagar> listar(){return repo.findAllByOrderByDataVencimentoAsc().stream().filter(e -> { try { if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId()); return true; } catch (org.springframework.security.access.AccessDeniedException ex) { return false; }}).toList();}}